    50	    { value: string } | undefined;
    51	  if (!meta) throw new Error('No document index. Run npm run setup or npm run ingest.');
    52	  if (meta.value !== config.embeddingModel)
    53	    throw new Error('The model does not match the index. Re-ingest the documents.');
    54	  const [queryVector] = await embedTexts([query]);
    55	  const scored = allChunks()
    56	    .filter((c) => role === 'operator' || c.audience === 'public')
    57	    .map(({ vector, ...c }) => {
    58	      if (vector!.length !== queryVector.length)
    59	        throw new Error('Incompatible embedding dimensions.');
    60	      const score = vector!.reduce((sum, v, i) => sum + v * queryVector[i], 0);
