    10	
    11	// Every chunk carries its document's title, version and validity window (the index only stores
    12	// them on a document's first chunk), so the agent can tell current terms from archived ones.
    13	// Ranking keeps current sources first, admits at most one historical/future source, and caps
    14	// chunks per document so one long document cannot crowd out the others.
    15	export function rankSources(scored: SearchResult[], limit: number) {
    16	  const manifest = new Map<string, DocumentRecord>(documents().map((d) => [d.id, d]));
    17	  const enriched = scored
    18	    .map((s) => {
    19	      const doc = manifest.get(s.documentId);
    20	      const meta = doc
    21	        ? { title: doc.title, version: doc.version, validFrom: doc.validFrom, validTo: doc.validTo }
    22	        : {};
    23	      const withMeta = { ...s, ...meta };
    24	      return { ...withMeta, validity: sourceValidity(withMeta) } as SearchResult;
    25	    })
    26	    .sort((a, b) => b.score - a.score);
    27	  const picked: SearchResult[] = [],
    28	    perDoc = new Map<string, number>();
    29	  let outOfDate = 0;
    30	  for (const s of enriched) {
    31	    if (picked.length === limit) break;
    32	    if ((perDoc.get(s.documentId) || 0) >= perDocument) continue;
    33	    if (s.validity !== 'current' && outOfDate >= 1) continue;
    34	    if (s.validity !== 'current') outOfDate++;
    35	    perDoc.set(s.documentId, (perDoc.get(s.documentId) || 0) + 1);
    36	    picked.push(s);
    37	  }
    38	  return picked.sort(
    39	    (a, b) =>
    40	      Number(a.validity !== 'current') - Number(b.validity !== 'current') || b.score - a.score,
    41	  );
    42	}
