  1	import { randomUUID } from 'node:crypto';
  2	import { z } from 'zod';
  3	import { appDb } from '../db';
  4	import { HttpError } from '../auth';
  5	import { person } from '../people';
  6	import { authorizeTransfer } from './authorization';
  7	import { dispatchTransfer, verifyTransfer, type DispatchOutcome } from './dispatch';
  8	import { recordEvent } from '../telemetry';
  9	import type { ActionResult, Operation, ToolContext, TransferInput } from '../types';
 10	
 11	export const transferSchema = z
 12	  .object({
 13	    fromAccountId: z.string().min(1),
 14	    toAccountId: z.string().min(1),
 15	    amountCents: z.number().int().positive().max(10000000),
 16	    concept: z.string().max(200),
 17	  })
 18	  .strict();
 19	export const approvalTtlMs = 10 * 60 * 1000;
 20	
 21	// Intent lifecycle:
 22	//   awaiting_confirmation -> submitting -> completed | rejected | not_executed | pending_verification
 23	//   awaiting_confirmation -> cancelled
 24	//   pending_verification  -> completed | not_executed   (by looking the fixed reference up)
 25	// "failed" only exists in records created before this lifecycle; it is treated as unverified.
 26	export type IntentRow = {
 27	  id: string;
 28	  user_id: string;
 29	  conversation_id: string | null;
 30	  run_id: string | null;
 31	  payload: string;
 32	  status: string;
 33	  bank_reference: string | null;
 34	  operation_id: string | null;
 35	  error: string | null;
 36	  created_at: string;
 37	};
 38	type ApprovalRow = {
 39	  id: string;
 40	  user_id: string;
 41	  intent_id: string;
 42	  payload: string;
 43	  expires_at: string;
 44	  consumed_at: string | null;
 45	};
 46	
 47	// Intent ids supplied by clients are scoped to the customer, so one customer's id can neither
 48	// collide with nor reveal another customer's intent.
 49	const storageId = (userId: string, intentId: string) => `${userId}:${intentId}`;
 50	const publicId = (row: IntentRow) =>
 51	  row.id.startsWith(`${row.user_id}:`) ? row.id.slice(row.user_id.length + 1) : row.id;
 52	const euros = (cents: number) => `${(cents / 100).toFixed(2)} EUR`;
 53	
 54	function findIntent(userId: string, id: string) {
 55	  return appDb()
 56	    .prepare('SELECT * FROM intents WHERE user_id=? AND id IN (?,?)')
 57	    .get(userId, storageId(userId, id), id) as IntentRow | undefined;
 58	}
 59	function intentById(id: string) {
 60	  return appDb().prepare('SELECT * FROM intents WHERE id=?').get(id) as IntentRow;
 61	}
 62	function pendingApproval(intentId: string) {
 63	  return appDb()
 64	    .prepare('SELECT * FROM approvals WHERE intent_id=? ORDER BY expires_at DESC LIMIT 1')
 65	    .get(intentId) as ApprovalRow | undefined;
 66	}
 67	function ctxFor(row: IntentRow, runId = randomUUID()): ToolContext {
 68	  return {
 69	    userId: row.user_id,
 70	    conversationId: row.conversation_id,
 71	    runId,
 72	    intentId: publicId(row),
 73	  };
 74	}
 75	
 76	export function describeIntent(row: IntentRow, operation?: Operation | null): ActionResult {
 77	  const payload = JSON.parse(row.payload) as TransferInput;
 78	  const base = { intentId: publicId(row), reference: row.bank_reference, payload };
 79	  switch (row.status) {
 80	    case 'awaiting_confirmation': {
 81	      const approval = pendingApproval(row.id);
 82	      if (!approval || approval.expires_at <= new Date().toISOString())
 83	        return {
 84	          status: 'expired',
 85	          ...base,
 86	          message: 'This proposal expired without being confirmed. No money moved.',
 87	        };
 88	      return {
 89	        status: 'requires_confirmation',
 90	        ...base,
 91	        approval: { id: approval.id, payload, expiresAt: approval.expires_at },
 92	        message: 'Waiting for the account holder to review and confirm the proposal.',
 93	      };
 94	    }
 95	    case 'submitting':
 96	      return { status: 'processing', ...base, message: 'The confirmed transfer is being sent.' };
 97	    case 'completed':
 98	      return {
 99	        status: 'completed',
100	        ...base,
101	        operationId: row.operation_id,
102	        ...(operation ? { operation } : {}),
103	        message: `The bank completed the transfer of ${euros(payload.amountCents)}.`,
104	      };
105	    case 'rejected':
106	      return {
107	        status: 'rejected',
108	        ...base,
109	        error: row.error,
110	        message: 'The bank rejected the transfer. No money moved.',
111	      };
112	    case 'not_executed':
113	      return {
114	        status: 'not_executed',
115	        ...base,
116	        error: row.error,
117	        message:
118	          'The bank has no record of this transfer, so no money moved. Sending it now needs a new proposal and confirmation.',
119	      };
120	    case 'pending_verification':
121	      return {
122	        status: 'pending_verification',
123	        ...base,
124	        error: row.error,
125	        message:
126	          'The bank did not answer, so it is not yet known whether the transfer was executed. Do not repeat it; check its status later.',
127	      };
128	    case 'cancelled':
129	      return {
130	        status: 'cancelled',
131	        ...base,
132	        message: 'The proposal was cancelled. No money moved.',
133	      };
134	    default:
135	      return {
136	        status: 'unverified',
137	        ...base,
138	        error: row.error,
139	        message: 'This record predates verification. Check its status against the bank.',
140	      };
141	  }
142	}
143	
144	// Customer intent -> proposal. Nothing is sent to the bank here: the holder must review the
145	// amount, source, destination and description and confirm them through the application.
146	export async function transferMoney(ctx: ToolContext, args: unknown): Promise<ActionResult> {
147	  if (person(ctx.userId)?.role !== 'customer')
148	    throw new HttpError(403, 'A customer account is required.');
149	  const input = transferSchema.parse(args),
150	    payload = JSON.stringify(input),
151	    db = appDb();
152	  const existing = findIntent(ctx.userId, ctx.intentId);
153	  if (existing) {
154	    if (existing.payload !== payload)
155	      throw new HttpError(409, 'This intent already exists with different details.');
156	    return describeIntent(existing);
157	  }
158	  if (ctx.dedupeProposals && ctx.conversationId) {
159	    const open = db
160	      .prepare(
161	        `SELECT i.* FROM intents i JOIN approvals a ON a.intent_id=i.id
162	         WHERE i.user_id=? AND i.conversation_id=? AND i.status='awaiting_confirmation'
163	           AND i.payload=? AND a.consumed_at IS NULL AND a.expires_at>? LIMIT 1`,
164	      )
165	      .get(ctx.userId, ctx.conversationId, payload, new Date().toISOString()) as
166	      IntentRow | undefined;
167	    if (open) return describeIntent(open);
168	  }
169	  const permission = await authorizeTransfer(ctx.userId, input);
170	  if (!permission.ok) {
171	    recordEvent(ctx, 'transfer.rejected', { status: 'rejected', input, error: permission.error });
172	    return {
173	      status: 'rejected',
174	      code: permission.code,
175	      error: permission.error,
176	      intentId: ctx.intentId,
177	    };
178	  }
179	  const id = storageId(ctx.userId, ctx.intentId),
180	    now = new Date(),
181	    approvalId = randomUUID(),
182	    reference = `bb-${randomUUID()}`,
183	    expiresAt = new Date(now.getTime() + approvalTtlMs).toISOString();
184	  const created = db.transaction(() => {
185	    const raced = findIntent(ctx.userId, ctx.intentId);
186	    if (raced) return raced;
187	    db.prepare('INSERT INTO intents VALUES(?,?,?,?,?,?,?,?,?,?)').run(
188	      id,
189	      ctx.userId,
190	      ctx.conversationId,
191	      ctx.runId,
192	      payload,
193	      'awaiting_confirmation',
194	      reference,
195	      null,
196	      null,
197	      now.toISOString(),
198	    );
199	    db.prepare('INSERT INTO approvals VALUES(?,?,?,?,?,?)').run(
200	      approvalId,
201	      ctx.userId,
202	      id,
203	      payload,
204	      expiresAt,
205	      null,
206	    );
207	    return null;
208	  })();
209	  if (created) {
210	    if (created.payload !== payload)
211	      throw new HttpError(409, 'This intent already exists with different details.');
212	    return describeIntent(created);
213	  }
214	  recordEvent(ctx, 'transfer.proposed', { status: 'requires_confirmation', input, reference });
215	  return {
216	    status: 'requires_confirmation',
217	    intentId: ctx.intentId,
218	    reference,
219	    approval: { id: approvalId, payload: input, summary: permission.parties, expiresAt },
220	    message:
221	      'Proposal created. The customer must review and confirm it in the application; it has not been sent to the bank.',
222	  };
223	}
224	
225	function applyOutcome(row: IntentRow, outcome: DispatchOutcome, ctx: ToolContext) {
226	  const db = appDb();
227	  if (outcome.kind === 'completed') {
228	    db.prepare('UPDATE intents SET status=?,operation_id=?,error=NULL WHERE id=?').run(
229	      'completed',
230	      outcome.operation.id,
231	      row.id,
232	    );
233	    recordEvent(ctx, 'transfer.completed', {
234	      status: 'completed',
235	      reference: row.bank_reference,
236	      operation: outcome.operation,
237	    });
238	    return describeIntent(intentById(row.id), outcome.operation);
239	  }
240	  const status =
241	    outcome.kind === 'rejected'
242	      ? 'rejected'
243	      : outcome.kind === 'not_executed'
244	        ? 'not_executed'
245	        : 'pending_verification';
246	  db.prepare('UPDATE intents SET status=?,error=? WHERE id=?').run(status, outcome.error, row.id);
247	  recordEvent(ctx, `transfer.${status}`, {
248	    status,
249	    reference: row.bank_reference,
250	    error: outcome.error,
251	  });
252	  return describeIntent(intentById(row.id));
253	}
254	
255	function noteInConversation(row: IntentRow, result: ActionResult, runId: string) {
256	  if (!row.conversation_id) return;
257	  const p = JSON.parse(row.payload) as TransferInput;
258	  appDb()
259	    .prepare('INSERT INTO messages VALUES(?,?,?,?,?,?)')
260	    .run(
261	      randomUUID(),
262	      row.conversation_id,
263	      'assistant',
264	      `Transfer update: ${euros(p.amountCents)} from ${p.fromAccountId} to ${p.toAccountId} ("${p.concept}") is **${String(result.status).replace(/_/g, ' ')}**. ${result.message} Reference: ${row.bank_reference}.`,
265	      new Date().toISOString(),
266	      runId,
267	    );
268	}
269	
270	// The only path that sends a transfer to the bank: an unexpired, unconsumed proposal confirmed by
271	// its holder. Consuming the proposal and claiming the intent happen atomically, so repeated or
272	// concurrent confirmations return the intent's state instead of sending it again.
273	export async function confirmApproval(userId: string, approvalId: string) {
274	  const db = appDb();
275	  const approval = db
276	    .prepare('SELECT * FROM approvals WHERE id=? AND user_id=?')
277	    .get(approvalId, userId) as ApprovalRow | undefined;
278	  if (!approval) throw new HttpError(404, 'Proposal not found.');
279	  const intent = db
280	    .prepare('SELECT * FROM intents WHERE id=? AND user_id=?')
281	    .get(approval.intent_id, userId) as IntentRow | undefined;
282	  if (!intent) throw new HttpError(404, 'Intent not found.');
283	  if (intent.payload !== approval.payload)
284	    throw new HttpError(409, 'The proposal no longer matches the transfer details.');
285	  const now = new Date().toISOString();
286	  const claimed = db.transaction(() => {
287	    const consumed = db
288	      .prepare(
289	        'UPDATE approvals SET consumed_at=? WHERE id=? AND consumed_at IS NULL AND expires_at>?',
290	      )
291	      .run(now, approval.id, now).changes;
292	    if (!consumed) return false;
293	    const updated = db
294	      .prepare(
295	        "UPDATE intents SET status='submitting' WHERE id=? AND status='awaiting_confirmation'",
296	      )
297	      .run(intent.id).changes;
298	    if (!updated) throw new HttpError(409, 'This transfer is no longer awaiting confirmation.');
299	    return true;
300	  })();
301	  if (!claimed) {
302	    const current = intentById(intent.id);
303	    if (current.status === 'awaiting_confirmation')
304	      throw new HttpError(409, 'This proposal has expired. Ask for a new transfer proposal.');
305	    if (current.status === 'cancelled') throw new HttpError(409, 'This proposal was cancelled.');
306	    return operationStatus(userId, publicId(current));
307	  }
308	  const ctx = ctxFor(intent);
309	  recordEvent(ctx, 'transfer.confirmed', {
310	    status: 'submitting',
311	    reference: intent.bank_reference,
312	  });
313	  const result = applyOutcome(
314	    intent,
315	    await dispatchTransfer(userId, intent.bank_reference!, JSON.parse(intent.payload)),
316	    ctx,
317	  );
318	  noteInConversation(intent, result, ctx.runId);
319	  return result;
320	}
321	
322	export function cancelApproval(userId: string, approvalId: string) {
323	  const db = appDb();
324	  const approval = db
325	    .prepare('SELECT * FROM approvals WHERE id=? AND user_id=?')
326	    .get(approvalId, userId) as ApprovalRow | undefined;
327	  if (!approval) throw new HttpError(404, 'Proposal not found.');
328	  db.transaction(() => {
329	    const consumed = db
330	      .prepare('UPDATE approvals SET consumed_at=? WHERE id=? AND consumed_at IS NULL')
331	      .run(new Date().toISOString(), approval.id).changes;
332	    if (consumed)
333	      db.prepare(
334	        "UPDATE intents SET status='cancelled' WHERE id=? AND status='awaiting_confirmation'",
335	      ).run(approval.intent_id);
336	  })();
337	  const intent = intentById(approval.intent_id);
338	  if (intent.status === 'cancelled')
339	    recordEvent(ctxFor(intent), 'transfer.cancelled', { status: 'cancelled' });
340	  return describeIntent(intent);
341	}
342	
343	// Status of an intent (by intent id or bank reference) or of a bare bank reference, always
344	// re-checked against the ledger when the application's own record is not final.
345	export async function operationStatus(userId: string, reference: string): Promise<ActionResult> {
346	  const intent =
347	    findIntent(userId, reference) ||
348	    (appDb()
349	      .prepare('SELECT * FROM intents WHERE user_id=? AND bank_reference=?')
350	      .get(userId, reference) as IntentRow | undefined);
351	  if (!intent) {
352	    const outcome = await verifyTransfer(userId, reference);
353	    if (outcome.kind === 'completed') return { status: 'completed', operation: outcome.operation };
354	    if (outcome.kind === 'not_executed')
355	      return { status: 'not_found', error: 'The bank has no operation with this reference.' };
356	    return { status: 'unavailable', error: 'The bank could not be queried. Try again later.' };
357	  }
358	  if (
359	    ['awaiting_confirmation', 'cancelled', 'submitting'].includes(intent.status) ||
360	    !intent.bank_reference
361	  )
362	    return describeIntent(intent);
363	  const outcome = await verifyTransfer(userId, intent.bank_reference);
364	  if (outcome.kind === 'completed') {
365	    if (intent.status !== 'completed') return applyOutcome(intent, outcome, ctxFor(intent));
366	    return describeIntent(intent, outcome.operation);
367	  }
368	  if (outcome.kind === 'not_executed' && ['pending_verification', 'failed'].includes(intent.status))
369	    return applyOutcome(intent, outcome, ctxFor(intent));
370	  return {
371	    ...describeIntent(intent),
372	    ...(outcome.kind === 'unknown' ? { verified: false, error: outcome.error } : {}),
373	  };
374	}
375	
376	export function recentIntents(userId: string) {
377	  return (
378	    appDb()
379	      .prepare(
380	        "SELECT * FROM intents WHERE user_id=? AND status NOT IN ('awaiting_confirmation','cancelled') ORDER BY created_at DESC LIMIT 10",
381	      )
382	      .all(userId) as IntentRow[]
383	  ).map((row) => describeIntent(row));
384	}
385	
386	export function conversationIntents(userId: string, conversationId: string) {
387	  return (
388	    appDb()
389	      .prepare('SELECT * FROM intents WHERE user_id=? AND conversation_id=? ORDER BY created_at')
390	      .all(userId, conversationId) as IntentRow[]
391	  ).map((row) => describeIntent(row));
392	}

