 56	    .prepare('SELECT * FROM intents WHERE user_id=? AND id IN (?,?)')
 57	    .get(userId, storageId(userId, id), id) as IntentRow | undefined;
 58	}
 59	function intentById(id: string) {
 60	  return appDb().prepare('SELECT * FROM intents WHERE id=?').get(id) as IntentRow;
 61	}
 62	function pendingApproval(intentId: string) {
 63	  return appDb()
 64	    .prepare('SELECT * FROM approvals WHERE intent_id=? ORDER BY expires_at DESC LIMIT 1')
 65	    .get(intentId) as ApprovalRow | undefined;
 66	}
 67	function ctxFor(row: IntentRow, runId = randomUUID()): ToolContext {
 68	  return {
 69	    userId: row.user_id,
 70	    conversationId: row.conversation_id,
 71	    runId,
 72	    intentId: publicId(row),
 73	  };
 74	}
