     1	import { bankRequest } from './client';
     2	import type { Account, TransferInput } from '../types';
     3	
     4	export type Contact = { id: string; userId: string; label: string; iban: string; name?: string };
     5	export type TransferParties = { from: Account; to: { id: string; label: string; name: string } };
     6	export type AuthorizationResult =
     7	  { ok: true; parties: TransferParties } | { ok: false; code: string; error: string };
     8	
     9	// Checks what the application can know before proposing: the source belongs to the session's
    10	// customer, the destination exists and differs, and the current balance covers the amount.
    11	// The bank remains authoritative and re-checks everything when the confirmed intent is sent.
    12	export async function authorizeTransfer(
    13	  userId: string,
    14	  input: TransferInput,
    15	): Promise<AuthorizationResult> {
    16	  const [accounts, contacts] = await Promise.all([
    17	    bankRequest<Account[]>(userId, '/v1/accounts'),
    18	    bankRequest<Contact[]>(userId, '/v1/contacts'),
    19	  ]);
    20	  const from = accounts.find((a) => a.id === input.fromAccountId);
    21	  if (!from)
    22	    return {
    23	      ok: false,
    24	      code: 'forbidden_account',
    25	      error: 'The source account does not belong to this customer.',
    26	    };
    27	  if (input.toAccountId === from.id)
    28	    return { ok: false, code: 'same_account', error: 'Source and destination must differ.' };
    29	  const own = accounts.find((a) => a.id === input.toAccountId);
    30	  const contact = contacts.find((c) => c.id === input.toAccountId);
    31	  if (!own && !contact)
    32	    return {
    33	      ok: false,
    34	      code: 'unknown_destination',
    35	      error: 'The destination account does not exist.',
    36	    };
    37	  if (from.balanceCents < input.amountCents)
    38	    return {
    39	      ok: false,
    40	      code: 'insufficient_funds',
    41	      error: `Insufficient funds: ${from.label} has ${(from.balanceCents / 100).toFixed(2)} EUR available.`,
    42	    };
    43	  const to = own
    44	    ? { id: own.id, label: own.label, name: 'Your own account' }
    45	    : { id: contact!.id, label: contact!.label, name: contact!.name || contact!.userId };
    46	  return { ok: true, parties: { from, to } };
    47	}
