     4	export function sign(value: string, secret: string) {
     5	  return createHmac('sha256', secret).update(value).digest('hex');
     6	}
     7	export function equal(a: string, b: string) {
     8	  const left = Buffer.from(a),
     9	    right = Buffer.from(b);
    10	  return left.length === right.length && timingSafeEqual(left, right);
    11	}
    12	export function sessionToken(userId: string) {
    13	  return `${userId}.${sign(userId, config.sessionSecret)}`;
    14	}
    15	export function actor(request: Request) {
    16	  const token = (request.headers.get('cookie') || '')
    17	    .split(';')
    18	    .map((s) => s.trim())
    19	    .find((s) => s.startsWith('banana_actor='))
    20	    ?.slice('banana_actor='.length);
    21	  if (!token) throw new HttpError(401, 'Select a person to continue.');
    22	  const [id, signature] = token.split('.');
    23	  const p = person(id);
    24	  if (!p || !signature || !equal(signature, sign(id, config.sessionSecret)))
    25	    throw new HttpError(401, 'Invalid session.');
    26	  return p;
    27	}
    28	export function sameOrigin(request: Request) {
    29	  const origin = request.headers.get('origin');
    30	  if (origin) {
    31	    const parsed = new URL(origin);
    32	    if (
    33	      !['http:', 'https:'].includes(parsed.protocol) ||
    34	      parsed.host !== request.headers.get('host')
    35	    )
    36	      throw new HttpError(403, 'Origin not allowed.');
    37	  }
    38	}
