     2	import type { Operation, TransferInput } from '../types';
     3	
     4	export type DispatchOutcome =
     5	  | { kind: 'completed'; operation: Operation }
     6	  | { kind: 'rejected'; status: number; error: string }
     7	  | { kind: 'not_executed'; error: string }
     8	  | { kind: 'unknown'; error: string };
     9	
    10	const attempts = 3;
    11	const pause = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
    12	
    13	// Sends one logical intent to the bank. The reference is fixed for the intent, so every retry is
    14	// the same request from the bank's point of view: a commit whose response was lost comes back as
    15	// a replay instead of a second transfer. A transport error or 5xx never proves a rejection, so
    16	// after the last attempt the outcome is verified by reference before anything is reported.
    17	export async function dispatchTransfer(
    18	  userId: string,
    19	  reference: string,
    20	  input: TransferInput,
    21	): Promise<DispatchOutcome> {
    22	  let lastError = 'No response received from the bank.';
    23	  for (let attempt = 0; attempt < attempts; attempt++) {
    24	    try {
    25	      const operation = await bankRequest<Operation>(userId, '/v1/transfers', 'POST', {
    26	        ...input,
    27	        reference,
    28	      });
    29	      return { kind: 'completed', operation };
    30	    } catch (e) {
    31	      if (!(e instanceof BankError)) throw e;
    32	      if (e.status < 500) return { kind: 'rejected', status: e.status, error: e.message };
    33	      lastError = e.message;
    34	      if (attempt < attempts - 1) await pause(200 * (attempt + 1));
    35	    }
    36	  }
    37	  return verifyTransfer(userId, reference, lastError);
    38	}
    39	
    40	// Looks the reference up in the ledger: found means completed, 404 means the bank never recorded
    41	// it, and any other failure leaves the outcome unknown (never reported as a failure).
    42	export async function verifyTransfer(
    43	  userId: string,
    44	  reference: string,
    45	  previousError = 'The bank did not confirm the operation.',
    46	): Promise<DispatchOutcome> {
    47	  try {
    48	    const operation = await bankRequest<Operation>(
    49	      userId,
    50	      `/v1/operations/${encodeURIComponent(reference)}`,
    51	    );
    52	    return { kind: 'completed', operation };
    53	  } catch (e) {
    54	    if (e instanceof BankError && e.status === 404)
    55	      return { kind: 'not_executed', error: previousError };
    56	    return { kind: 'unknown', error: e instanceof Error ? e.message : previousError };
    57	  }
    58	}
