    18	// Everything an operator needs for a case, taken only from recorded evidence: the conversation,
    19	// the agent's recorded steps, the transfer intents and the bank ledger. Missing records and
    20	// disagreements between the application and the bank are listed as gaps, never filled in.
    21	export async function caseDetail(operatorId: string, id: string) {
    22	  if (person(operatorId)?.role !== 'operator') throw new HttpError(403, 'Operator role required.');
    23	  const db = appDb();
    24	  const incident = db.prepare('SELECT * FROM incidents WHERE id=?').get(id) as Incident | undefined;
    25	  if (!incident) throw new HttpError(404, 'Case not found.');
    26	  const history = db
    27	    .prepare('SELECT * FROM messages WHERE conversation_id=? ORDER BY created_at,rowid')
    28	    .all(incident.conversation_id) as { id: string; content: string }[];
    29	  const events = (
    30	    db
    31	      .prepare('SELECT * FROM events WHERE conversation_id=? ORDER BY created_at,rowid')
    32	      .all(incident.conversation_id) as EventRow[]
    33	  ).map((e) => ({ ...e, data: JSON.parse(e.data) }));
    34	  const intentRows = db
    35	    .prepare('SELECT * FROM intents WHERE conversation_id=? AND user_id=? ORDER BY created_at')
    36	    .all(incident.conversation_id, incident.user_id) as IntentRow[];
    37	  const gaps: string[] = [];
    38	  let bank: { accounts: Account[]; operations: Operation[] } | null = null;
    39	  try {
    40	    bank = await bankRequest(
    41	      operatorId,
    42	      `/v1/operator/customer?id=${encodeURIComponent(incident.user_id)}`,
    43	    );
    44	  } catch (e) {
    45	    gaps.push(
    46	      `The bank could not be queried (${e instanceof Error ? e.message : 'error'}); bank effects are unverified.`,
    47	    );
    48	  }
    49	  if (!events.length)
    50	    gaps.push(
    51	      'No agent activity was recorded for this conversation. Steps that were not recorded are not reconstructed.',
    52	    );
    53	  const intents = intentRows.map((row) => {
    54	    const operation = bank?.operations.find((o) => o.reference === row.bank_reference) || null;
    55	    const described = describeIntent(row);
    56	    if (bank) {
    57	      if (operation && row.status !== 'completed')
    58	        gaps.push(
    59	          `Intent ${described.intentId} is recorded as "${row.status}" in the application, but the bank ledger shows completed operation ${operation.id} (${(operation.amountCents / 100).toFixed(2)} EUR, reference ${operation.reference}). Money did move.`,
    60	        );
    61	      if (!operation && row.status === 'completed')
    62	        gaps.push(
    63	          `Intent ${described.intentId} is recorded as completed but no bank operation has reference ${row.bank_reference}.`,
    64	        );
    65	    }
    66	    return { ...described, createdAt: row.created_at, bankOperation: operation };
    67	  });
    68	  return {
    69	    incident,
    70	    customer: person(incident.user_id),
    71	    lastMessage: history.at(-1) || null,
    72	    history,
    73	    events,
    74	    intents,
    75	    bank,
    76	    gaps: gaps.join('\n'),
    77	  };
    78	}
