// Accepts "12.50", "12,50", "1,234.56" and "1.234,56". With a single separator, exactly three
// digits after it mean thousands ("1.234" = 1234 EUR). Returns null when the amount is unclear.
export function parseAmountCents(value: string): number | null {
  const v = value.replace(/[\s€]|EUR/gi, '');
  if (!/^\d[\d.,]*$/.test(v)) return null;
  const last = Math.max(v.lastIndexOf('.'), v.lastIndexOf(','));
  let whole = v,
    decimals = '';
  if (last >= 0) {
    const tail = v.slice(last + 1),
      separators = v.match(/[.,]/g)?.length ?? 0,
      mixed = v.includes('.') && v.includes(',');
    if (mixed || (separators === 1 && tail.length !== 3)) {
      whole = v.slice(0, last);
      decimals = tail;
    }
  }
  if (decimals.length > 2 || /[.,]/.test(decimals)) return null;
  const digits = whole.replace(/[.,]/g, '');
  if (!digits) return null;
  return Number(digits) * 100 + Number(decimals.padEnd(2, '0') || 0);
}

